(()=>{'use strict';
const activities=[{id:'herbs',name:'Gather herbs',icon:'🌿',skill:'Foraging',desc:'A handful of useful weeds.',resource:'herbs',yield:1,xp:7,caption:'Your hero is contemplating a suspiciously leafy shrub.',quote:'“Ah yes, gathering herbs. The ancient art of standing near plants and calling it a career.”'},{id:'wood',name:'Chop wood',icon:'🪓',skill:'Woodcraft',desc:'Timber! Very satisfying.',resource:'wood',yield:1,xp:8,caption:'A tree has been asked politely to become firewood.',quote:'“The trees are nervous. Your hero has a tiny axe and absolutely no forestry license.”'},{id:'mine',name:'Mine ore',icon:'⛏️',skill:'Mining',desc:'Rock collection, but profitable.',resource:'ore',yield:1,xp:9,caption:'The rocks are putting up a brave, mostly geological, fight.',quote:'“You found a rock! It is worth money, unlike most rocks people find.”'},{id:'fish',name:'Go fishing',icon:'🎣',skill:'Fishing',desc:'Stare at water. Professionally.',resource:'fish',yield:1,xp:8,caption:'A fish has made a questionable life choice.',quote:'“Fishing: staring at water until lunch happens. Civilization is wonderful.”'},{id:'combat',name:'Fight slimes',icon:'⚔️',skill:'Combat',desc:'Bonk a gelatinous menace.',resource:'coins',yield:3,xp:12,caption:'A brave duel is underway. The slime seems mildly confused.',quote:'“The slime has been defeated. It was mostly water and bad intentions.”'},{id:'pray',name:'Pray (ish)',icon:'🙏',skill:'Faith',desc:'Ask the cosmos for a favor.',resource:'favor',yield:1,xp:6,caption:'Your hero is negotiating with the infinite. Terms are vague.',quote:'“A prayer! I shall answer it after I finish this extremely important cloud.”'}];
const resourcesDef=[['herbs','🌿','Herbs'],['wood','🪵','Wood'],['ore','🪨','Ore'],['fish','🐟','Fish'],['coins','🪙','Coins'],['favor','✨','Favor']];const skillIcons={Foraging:'🌿',Woodcraft:'🪓',Mining:'⛏️',Fishing:'🎣',Combat:'⚔️',Faith:'🙏'};const quests=[['herbs','🌿','A modest pile of herbs',12],['wood','🪵','A tree-mendous effort',15],['ore','🪨','The motherlode-ish',12],['fish','🐟','Fish for compliments',10],['coins','🪙','A hero needs pocket money',30],['combat','⚔️','Slime happens',8]];
const fresh=()=>({resources:{herbs:0,wood:0,ore:0,fish:0,coins:0,favor:12},skills:Object.fromEntries(Object.keys(skillIcons).map(k=>[k,0])),heroXP:0,activity:'herbs',paused:false,rate:1,bonus:1,questIndex:0,questProgress:0,heroName:'Pip',events:[],last:Date.now(),upgrades:{satchel:0,charm:0,sword:0}});let s;try{s={...fresh(),...JSON.parse(localStorage.getItem('oddgods-save')||'{}')};s.resources={...fresh().resources,...s.resources};s.skills={...fresh().skills,...s.skills};s.upgrades={...fresh().upgrades,...s.upgrades};}catch{s=fresh()}let toastTimer;
const fmt=n=>{if(n>=1e12)return (n/1e12).toFixed(2)+'T';if(n>=1e9)return (n/1e9).toFixed(2)+'B';if(n>=1e6)return (n/1e6).toFixed(2)+'M';if(n>=1e4)return (n/1e3).toFixed(1)+'K';return Math.floor(n).toLocaleString()};const level=x=>Math.max(1,Math.floor((-25+Math.sqrt(625+60*Math.max(0,x)))/30)+1);const xpFor=l=>30*l*(l-1)/2+50*(l-1);const toast=m=>{let e=document.querySelector('#toast');e.textContent=m;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2500)};const current=()=>activities.find(a=>a.id===s.activity)||activities[0];
function log(text,icon='✨'){s.events.unshift({text,icon,time:Date.now()});s.events=s.events.slice(0,8)}function questAction(id,amount){let q=quests[s.questIndex];let key=q[0]==='combat'?'coins':q[0];if(id!==q[0])return;let n=Math.floor((s.questProgress+amount)/q[3]);s.questProgress=(s.questProgress+amount)%q[3];if(n>0){s.resources.coins+=n*10;s.resources.favor+=n*3;log(`Prophecy fulfilled! +${fmt(n*10)} coins and ${fmt(n*3)} favor.`,'📜');toast('Prophecy fulfilled! The gods are insufferably pleased.');s.questIndex=(s.questIndex+Math.min(n,quests.length))%quests.length}}
function act(id,count=1,manual=false){let a=activities.find(x=>x.id===id)||current();if(count<=0)return;let amount=count*a.yield*s.bonus;if(a.resource==='favor')s.resources.favor+=amount;else s.resources[a.resource]+=amount;if(a.id==='combat'){s.resources.herbs+=0;let coins=amount;s.resources.essence=(s.resources.essence||0)+count*.2*(1+s.upgrades.sword);questAction('combat',coins)}else questAction(a.id,amount);s.skills[a.skill]=(s.skills[a.skill]||0)+count*a.xp;s.heroXP+=count*(a.xp+2);if(manual){log(`${a.icon} ${a.name}: +${fmt(amount)} ${a.resource==='favor'?'favor':a.resource}.`,a.icon);render()}}
function renderActivity(){document.querySelector('#activityGrid').innerHTML=activities.map(a=>`<button class="activity-btn ${s.activity===a.id?'selected':''}" data-act="${a.id}"><span class="activity-icon">${a.icon}</span><span class="activity-name">${a.name}</span><span class="activity-rate">${a.desc}</span></button>`).join('');document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{s.activity=b.dataset.act;log(`${current().icon} Set off to ${current().name.toLowerCase()}.`,current().icon);render();toast(`${current().name} — away we go!`)})}
function render(){const a=current();renderActivity();document.querySelector('#favor').textContent=fmt(s.resources.favor);document.querySelector('#currentActivity').textContent=s.paused?'Taking a little breather':a.name;document.querySelector('#activityIcon').textContent=s.paused?'💤':a.icon;document.querySelector('#rateLabel').textContent=s.paused?'0':(s.rate*(1+s.upgrades.charm*.25)).toFixed(1).replace(/\.0$/,'');document.querySelector('#sceneCaption').textContent=s.paused?'Your hero is resting. Even legends need a snack break.':a.caption;document.querySelector('#godQuote').textContent=s.paused?'“Finally, a moment of peace. I was getting tired of narrating.”':a.quote;document.querySelector('#pauseBtn').textContent=s.paused?'▶ Resume':'Ⅱ Pause';
let lv=level(s.heroXP),prog=s.heroXP-xpFor(lv),need=xpFor(lv+1)-xpFor(lv);document.querySelector('#heroLevel').textContent=fmt(lv);document.querySelector('#xpLabel').textContent=`${fmt(prog)} / ${fmt(need)} XP`;document.querySelector('#heroXp').style.width=Math.min(100,prog/need*100)+'%';let q=quests[s.questIndex],key=q[0]==='combat'?'coins':q[0];document.querySelector('#questTitle').textContent=q[2];document.querySelector('#questProgress').textContent=`${fmt(s.questProgress)} / ${q[3]} ${q[0]==='combat'?'slimes':q[0]}`;document.querySelector('#questFill').style.width=Math.min(100,s.questProgress/q[3]*100)+'%';document.querySelector('#resources').innerHTML=resourcesDef.map(([k,i,n])=>`<div class="resource"><span class="resource-icon">${i}</span><strong>${fmt(s.resources[k]||0)}</strong><small>${n}</small></div>`).join('');document.querySelector('#skills').innerHTML=Object.entries(s.skills).map(([name,xp])=>{let l=level(xp),p=xp-xpFor(l),need=xpFor(l+1)-xpFor(l);return `<div class="skill-row"><span class="skill-emoji">${skillIcons[name]}</span><div class="skill-info"><strong>${name}</strong><div class="skill-bar"><i style="width:${Math.min(100,p/need*100)}%"></i></div></div><span class="skill-level">${fmt(l)}</span></div>`}).join('');document.querySelector('#skillNav').textContent=Object.keys(s.skills).length;document.querySelector('#eventLog').innerHTML=(s.events.length?s.events:[{text:'A new little legend begins. Your god is already taking credit.',icon:'🌟',time:Date.now()}]).slice(0,4).map(e=>`<div class="event-item"><b>${e.icon}</b><span>${e.text}</span><time>${ago(e.time)}</time></div>`).join('');document.querySelector('#topTab').textContent=(document.querySelector('.nav button.active')?.dataset.tab||'journey').toUpperCase();}
function ago(t){let n=Math.max(0,Math.floor((Date.now()-t)/1000));return n<60?'just now':n<3600?`${Math.floor(n/60)}m ago`:n<86400?`${Math.floor(n/3600)}h ago`:`${Math.floor(n/86400)}d ago`}
function save(){s.last=Date.now();localStorage.setItem('oddgods-save',JSON.stringify(s));document.querySelector('#saveStatus').textContent='All progress saved'}function offline(){let seconds=Math.max(0,(Date.now()-s.last)/1000);if(seconds>2&&!s.paused){let a=current(),rate=s.rate*(1+s.upgrades.charm*.25);act(s.activity,seconds*rate);log(`While you were away: ${fmt(seconds*rate)} ${a.name.toLowerCase()} actions.`, '⏳');toast(`Welcome back! ${fmt(seconds*rate)} idle actions happened while you were away.`)}s.last=Date.now()}
const upgrades=[{id:'satchel',name:'Bottomless-ish satchel',icon:'🎒',cost:{wood:15,herbs:10},desc:'Gather 25% more from every action.',buy:()=>s.bonus+=.25},{id:'charm',name:'Suspiciously lucky charm',icon:'🍀',cost:{coins:50,ore:5},desc:'Idle actions happen 25% faster.',buy:()=>{}},{id:'sword',name:'Sword with a point',icon:'🗡️',cost:{ore:12,coins:35},desc:'Combat pays 50% more coins and essence.',buy:()=>{}}];
function openModal(type){let title,body;if(type==='skills'){title='Skills & divine upgrades';body=`<p>Practice makes proficient. Proficient makes the gods look good. Spend your hard-earned loot on a small advantage.</p><div class="modal-list">${Object.entries(s.skills).map(([n,x])=>`<div class="modal-row"><span>${skillIcons[n]}</span><span>${n}</span><b>Level ${fmt(level(x))} · ${fmt(x)} XP</b></div>`).join('')}</div><h3 style="font:600 16px var(--serif);margin:22px 0 8px">A few questionable purchases</h3><div class="modal-list">${upgrades.map(u=>{let owned=s.upgrades[u.id];let costs=Object.entries(u.cost).map(([k,v])=>`${resourcesDef.find(x=>x[0]===k)?.[1]||'🪨'} ${v}`).join(' + ');return `<div class="modal-row"><span>${u.icon}</span><span><b>${u.name}</b><br><small>${u.desc}</small><br><small>${costs}${owned?' · owned ×'+owned:''}</small></span><button class="buy" data-buy="${u.id}" ${Object.entries(u.cost).some(([k,v])=>s.resources[k]<v)?'disabled':''}>Buy</button></div>`}).join('')}</div>`}else if(type==='quests'){title='Prophecies, allegedly';body=`<p>Your god has a plan. The plan is mostly collecting things and being paid in pocket change.</p><div class="modal-list">${quests.map((q,i)=>`<div class="modal-row"><span>${q[1]}</span><span>${q[2]}${i===s.questIndex?' · <b>ACTIVE</b>':''}</span><b>${i===s.questIndex?fmt(s.questProgress):'—'} / ${q[3]}</b></div>`).join('')}</div><p>Complete prophecies for coins and divine favor. They keep coming forever. Much like the universe.</p>`}else if(type==='log'){title='The Chronicle';body=`<p>A painstakingly accurate account of your hero’s increasingly improbable career.</p><div class="modal-list">${(s.events.length?s.events:[{text:'Nothing yet. The page is judging you silently.',icon:'📖',time:Date.now()}]).map(e=>`<div class="modal-row"><span>${e.icon}</span><span>${e.text}</span><b>${ago(e.time)}</b></div>`).join('')}</div>`}else{title='Pocket universe';body=`<p>Everything you have acquired while being heroically present or elsewhere.</p><div class="modal-list">${resourcesDef.map(([k,i,n])=>`<div class="modal-row"><span>${i}</span><span>${n}</span><b>${fmt(s.resources[k]||0)}</b></div>`).join('')}<div class="modal-row"><span>💠</span><span>Slime essence</span><b>${fmt(s.resources.essence||0)}</b></div></div>`}
document.querySelector('#modalContent').innerHTML=`<div class="eyebrow">ODDLY USEFUL INFORMATION</div><h2>${title}</h2>${body}`;document.querySelector('#modal').hidden=false;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));}
function buy(id){let u=upgrades.find(x=>x.id===id);if(!u||Object.entries(u.cost).some(([k,v])=>s.resources[k]<v)){toast('Not quite enough supplies, brave shopper.');return}Object.entries(u.cost).forEach(([k,v])=>s.resources[k]-=v);s.upgrades[id]++;if(id==='charm')s.rate+=.25;if(id==='satchel')s.bonus+=.25;log(`${u.icon} Bought ${u.name}. Your god approves (of the transaction).`,u.icon);toast(`${u.name} acquired!`);openModal('skills');render();save()}
document.querySelector('#activityGrid').addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(b){s.activity=b.dataset.act;render()}});document.querySelector('#pauseBtn').onclick=()=>{s.paused=!s.paused;log(s.paused?'Your hero decided to rest.':'Your hero is back at it.','💤');render();save()};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openModal(b.dataset.open));document.querySelector('#questButton').onclick=()=>openModal('quests');document.querySelector('#inventoryBtn').onclick=()=>openModal('inventory');document.querySelector('#closeModal').onclick=()=>document.querySelector('#modal').hidden=true;document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.hidden=true};document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x===b));let tab=b.dataset.tab;if(tab!=='journey')openModal(tab);render()});document.querySelector('#resetBtn').onclick=()=>{if(confirm('Start a fresh little universe? This erases the save on this device.')){localStorage.removeItem('oddgods-save');s=fresh();render();save();toast('A new universe. Same questionable gods.')}};
offline();render();let lastFrame=Date.now();setInterval(()=>{let now=Date.now(),dt=Math.max(0,(now-lastFrame)/1000);lastFrame=now;if(!s.paused){act(s.activity,dt*s.rate*(1+s.upgrades.charm*.25));s.last=now}render();save()},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){offline();render()}});
})();

