2: @media(max-width:1050px){.app{grid-template-columns:190px minmax(0,1fr)}.content{padding:23px 24px}.topbar{padding:0 24px}.activity-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.app{display:block}.sidebar{position:fixed;z-index:8;top:auto;bottom:0;width:100%;height:62px;min-height:0;padding:5px 8px calc(5px + env(safe-area-inset-bottom));display:block;border-top:1px solid #2b3b4e}.brand,.nav-label,.side-spacer,.side-quote,.save-status{display:none}.nav{height:100%;display:grid;grid-template-columns:repeat(4,1fr);gap:3px}.nav button{padding:4px 2px;display:flex;flex-direction:column;justify-content:center;gap:1px;text-align:center;font-size:9px;border-radius:8px}.nav button span{font-size:17px}.nav button b{display:none}.nav button.active{box-shadow:inset 0 2px #eab655}.topbar{height:50px;padding:0 17px}.content{padding:20px 14px 85px}.welcome{align-items:flex-start;gap:10px}.welcome h1{font-size:23px}.welcome p{font-size:10px}.hero-level{gap:7px;padding-top:5px}.level-seal{width:36px;height:36px}.xp-track{width:75px}.hero-level small{font-size:7px}.hero-level strong{font-size:8px}.scene-top,.scene-footer{padding:0 11px}.weather{font-size:8px}.landscape{height:175px}.dashboard-grid,.bottom-grid{grid-template-columns:1fr}.dashboard-grid{gap:10px}.panel{padding:15px}.activity-grid{grid-template-columns:repeat(4,1fr);gap:6px}.activity-btn{padding:8px 5px;min-height:65px}.activity-name{font-size:9px}.pill{font-size:7px}.god-panel{order:2}.bottom-grid{gap:10px}.resource-list{grid-template-columns:repeat(4,1fr)}.crumb{font-size:8px}.top-right{gap:11px}.event-item{min-width:145px}.scene-caption{font-size:8px}}@media(max-width:390px){.activity-grid{grid-template-columns:repeat(3,1fr)}.welcome h1{font-size:20px}.hero-level{gap:5px}.resource{padding:7px 5px;grid-template-columns:18px 1fr}.resource-icon{font-size:14px}.resource strong{font-size:9px}.scene-caption{font-size:7px}.weather{display:none}}

