input.content:
/* Combat and crafting additions */
.combat-status{margin:12px 0 2px;padding:12px 14px;background:#f7f6f0;border:1px solid var(--line);border-radius:11px}.battle-head{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px}.battle-head>span,.battle-bars small{font-size:9px;color:var(--muted)}.battle-bars{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:9px}.battle-bars small{display:block;margin-bottom:5px}.battle-track{height:7px;background:#e8e7e1;border-radius:8px;overflow:hidden}.battle-track i{height:100%;display:block;background:linear-gradient(90deg,#61aa7d,#9dc980);border-radius:inherit;transition:width .25s}.monster-track i{background:linear-gradient(90deg,#df8b62,#d85f5f)}.activity-actions{display:flex;gap:16px;align-items:center}.modal-subhead{font:600 16px var(--serif);margin:22px 0 8px}.craft-summary{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:15px 0;padding:11px 13px;background:#f6f5f0;border-radius:9px;font-size:11px;font-weight:700}.craft-summary span{color:#a7a39a}.recipe-row{align-items:center}.equipment-note{margin:14px 0;color:#586575;font-size:11px;font-weight:700}.modal-resources{margin:12px 0 18px}.buy{flex:0 0 auto}.buy:disabled{cursor:not-allowed;opacity:.48}
@media(max-width:760px){.activity-actions{gap:10px}.battle-bars{gap:8px}.battle-head{font-size:10px}.battle-head>span{font-size:8px}.combat-status{padding:10px}.nav button{font-size:8px}.nav button span{font-size:15px}}

input.command:
node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:900}}); const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.addInitScript(()=>localStorage.setItem('oddgods-save',JSON.stringify({resources:{herbs:20,wood:30,ore:30,fish:20,coins:100,favor:12,essence:0},skills:{Crafting:55},last:Date.now(),activity:'herbs'})));
 await page.goto('http://localhost:3002'); await page.locator('[data-act="combat"]').click(); await page.waitForTimeout(1500);
 const combat=await page.locator('#combatStatus').innerText();
 await page.locator('#craftButton').click(); const title=await page.locator('#modalContent h2').innerText();
 await page.locator('[data-craft="swords"]').click(); await page.locator('[data-craft="shields"]').click();
 const equipped=await page.locator('.equipment-note').innerText();
 console.log(JSON.stringify({combat,title,equipped,errors},null,2));
 await browser.close(); if(errors.length)process.exit(1);
})().catch(e=>{console.error(e);process.exit(1)});
